package com.logistics.notification;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.context.annotation.Bean;import org.springframework.amqp.core.*;import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;
@SpringBootApplication public class NotificationServiceApplication {public static void main(String[]a){SpringApplication.run(NotificationServiceApplication.class,a);} @Bean TopicExchange events(){return new TopicExchange("logistics.events");} @Bean Jackson2JsonMessageConverter jsonConverter(){return new Jackson2JsonMessageConverter();} @Bean Queue shipmentQueue(){return new Queue("notification.shipment-events");} @Bean Binding created(Queue shipmentQueue,TopicExchange events){return BindingBuilder.bind(shipmentQueue).to(events).with("ShipmentCreated");} @Bean Binding delivered(Queue shipmentQueue,TopicExchange events){return BindingBuilder.bind(shipmentQueue).to(events).with("ShipmentDelivered");}}

